Q: Doctrine DTO with native SQL queries A: <p>Or use <a href="https://www.doctrine-project.org/projects/doctrine-orm/en/3.6/reference/native-sql.html" rel="nofollow noreferrer"><code>ResultSetMapping</code></a>, taking <a href="https://stackoverflow.com/questions/34930702/doctrine-dto-with-native-sql-queries/36664938#36664938">@dion-truter's answer</a> as an example in Symfony:</p>
<pre class="lang-php prettyprint-override"><code>public function findRecentDateTotals2($taskId)
{
    $fromDate = new DateTime('6 days ago');
    $entityManager = $this-&gt;getEntityManager(); // Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository-&gt;getEntityManager()

    $rsm = new ResultSetMapping();
    $rsm-&gt;addEntityResult(DateTotal::class, 'task_log');
    $rsm-&gt;addFieldResult('task_log', 'taskLogDate', 'taskLogDate');
    $rsm-&gt;addFieldResult('task_log', 'totalHours', 'totalHours');
    // or
    $rsm = new ResultSetMappingBuilder($entityManager);
    $rsm-&gt;addRootEntityFromClassMetadata(DateTotal::class, 'task_log');

    return $entityManager-&gt;createNativeQuery(
        &lt;&lt;&lt;'SQL'
        SELECT
          task_log.task_log_date AS taskLogDate,
          SUM(task_log.task_log_hours) AS totalHours
        FROM task_log task_log
        WHERE (task_log.task_log_task = :taskId OR :taskId = 0) AND task_log.task_log_date &gt; :fromDate
        GROUP BY task_log_date
        ORDER BY task_log_date DESC        
        SQL, $rsm)
    -&gt;setParameters([
        'taskId' =&gt; $taskId,
        'fromDate' =&gt; $fromDate-&gt;format('Y-m-d')
    ])
    -&gt;getResult();
}
</code></pre>
<pre class="lang-php prettyprint-override"><code>use Doctrine\ORM\Mapping as ORM;

#[ORM\Entity]
class DateTotal
{
    public function __construct(
        #[ORM\Column, ORM\Id] public $taskLogDate = null,
        #[ORM\Column] public $totalHours = null
    ) {}
}
</code></pre>
